examples.template:
MonarchEditableCell({{label}}, value: $title, startsEditing: true) { _ in
    try await Task.sleep(for: .milliseconds(300))
}

examples.code:
MonarchEditableCell("Title", value: $title, startsEditing: true) { _ in
    try await Task.sleep(for: .milliseconds(300))
}

VStack(alignment: .leading) {
    MonarchEditableCell(
        "Status",
        value: $status,
        kind: .select,
        options: [
            MonarchEditableCellOption("Open", value: "open"),
            MonarchEditableCellOption("In review", value: "review"),
            MonarchEditableCellOption("Done", value: "done"),
        ]
    ) { _ in }
    MonarchEditableCell("Due", value: $due, kind: .date) { _ in }
}

MonarchEditableCell(
    "Owner",
    value: $owner,
    validate: { value in
        if case .text(let text) = value, text.count < 2 { return "Use at least 2 characters." }
        return nil
    },
    onCommit: { _ in }
)
